  'motylarnia.meter': 'Apetyt',
  'motylarnia.meterRest': 'Barwy',
  'arka.brainFocus': 'mgła po potopie ustępuje: jasny krąg wokół drzwi rośnie, a nad progiem wolne zwierzęta pokazują złote ślady',
  'arka.brainRest': 'spokój napełnia tęczę, która oddaje serce i wskazuje bezpieczny ruch',
  'arka.meter': 'Jasny krąg',
  'arka.meterRest': 'Blask tęczy',
