  'zacheusz.meterRest': 'Dojrzewanie fig',
  'pasterz.brainFocus': 'krąg wołania rośnie i przyciąga luźne owce, a utrzymane skupienie niesie Głos przez całe wzgórze',
  'pasterz.brainRest': 'spokój zapala gwiazdy, a każda gwiazda to zabłąkana owca, którą Łatek przyprowadza do stada',
  'pasterz.meter': 'Krąg wołania',
  'pasterz.meterRest': 'Gwiazdy nocy',
  'aniol.brainFocus': 'aura światła wokół łóżka rośnie, rani zmory i kruszy pancerze; utrzymane skupienie rozpala Płomień i Skrzydła ognia',
  'aniol.brainRest': 'spokój napełnia sen dziecka gwiazdami: Sen wraca i przybywa piór',
  'aniol.meter': 'Aura światła',
  'aniol.meterRest': 'Spokój kołysanki',
  'zastepy.brainFocus': 'światło płynie szybciej i wystawiasz więcej wojsk; utrzymane skupienie ładuje trąbę',
