  'firmament.brainFocus': 'światło wpada do teleskopu; pełny krąg to przyrząd: młot, promień, tasowanie albo +5 ruchów',
  'firmament.brainRest': 'spokojne niebo: spadające gwiazdy zostawiają komety i oddają dwa ruchy',
  'firmament.meter': 'Światło w obiektywie',
